mapper.select:
select `o`.*,u.real_name, d.real_name as doctor_real_name, dd.dept_name from `order` o   left join `user` u on o.user_id = u.id
   left join `user` d on o.doctor_user_id = d.id
   left join `dept` dd on o.dept_id = dd.id
   where 1=1

        and o.user_id = #{userId}


        and o.doctor_user_id = #{doctorUserId}


        and o.order_number = #{orderNumber}


        and o.time = #{time}


        and o.status = #{status}


        and o.dept_id = #{deptId}


        and u.real_name like concat('%',#{realName},'%')


        and d.real_name like concat('%',#{doctorRealName},'%')


        and dd.dept_name like concat('%',#{deptName},'%')

select COUNT(*) from `order`
where 1=1

    and `year`  = #{year}


    and `month`  = #{month}


    and `day`  = #{day}

select SUM(price) from `order`
where 1=1

    and `year`  = #{year}


    and `month`  = #{month}


    and `day`  = #{day}
